/**
 * The stack wall. Full-colour brand marks, baked in as raw SVG bodies so no
 * icon package ships at runtime. Sources: Iconify `logos` (CC0) for most,
 * `selfhst` for Hetzner, Simple Icons (CC0) for SQLite and Lucide (ISC) for
 * REST API — neither of which has a colour mark — and Wikimedia Commons for the
 * five Google marks, whose 2025/26 redesigns the icon sets have not shipped.
 *
 * Marks whose logo is near-black — OpenAI, AWS, GitHub — use the white lockup
 * each of those brands publishes for dark backgrounds. Every mark's strongest
 * colour clears 3:1 against the void at the wall's rest opacity (WCAG 1.4.11;
 * the marks carry meaning and have no caption), which the generator asserts.
 *
 * Order is the message's own path through the system and is deliberate:
 * channel, workspace, intelligence, data, infrastructure, application,
 * interface. The grouping is not labelled in the UI but it is why these sit in
 * this sequence, so keep additions inside the right run.
 *
 * Trademarks belong to their owners and appear here only to describe what this
 * system runs on.
 */
export type Mark = {
  name: string;
  /** Raw SVG children, colours baked in. Injected with dangerouslySetInnerHTML. */
  body?: string;
  /** Set instead of `body` for the one brand that publishes no vector mark. */
  img?: string;
  /** Intrinsic viewBox size; aspect ratios differ widely between brands. */
  w: number;
  h: number;
};

